{
  "implementation": "def solve(case):
    items = case['items']
    required = set(case['required_failure_items'])
    unresolved_without = set(case['unresolved_without'])

    def test(s):
        if not unresolved_without.issubset(s):
            return 'UNRESOLVED'
        if required.issubset(s):
            return 'FAIL'
        return 'PASS'

    full_set = set(items)
    test_count = 0
    test_count += 1
    if test(full_set) != 'FAIL':
        raise ValueError('Initial configuration must be FAIL')

    c = list(items)
    n = 2
    while True:
        if len(c) == 1:
            break
        size = len(c) // n
        remainder = len(c) % n
        subsets = []
        idx = 0
        for i in range(n):
            if i < remainder:
                subset_size = size + 1
            else:
                subset_size = size
            subsets.append(c[idx:idx+subset_size] if subset_size > 0 else [])
            idx += subset_size
        reduced = False
        tested = set()
        for sub in subsets:
            sub_set = frozenset(sub)
            if sub_set not in tested:
                test_count += 1
                res = test(sub_set)
                tested.add(sub_set)
                if res == 'FAIL':
                    c = sub
                    n = 2
                    reduced = True
                    break
            comp = [x for x in c if x not in sub]
            comp_set = frozenset(comp)
            if comp_set not in tested:
                test_count += 1
                res = test(comp_set)
                tested.add(comp_set)
                if res == 'FAIL':
                    c = comp
                    n = 2
                    reduced = True
                    break
        if not reduced:
            if n == len(c):
                break
            else:
                n = min(n * 2, len(c))
    test_count += 1
    if test(frozenset(c)) != 'FAIL':
        raise ValueError('Minimal failure must be FAIL')
    return {'minimal_failure': c, 'outcome': 'FAIL', 'tests': test_count}
